#!/usr/bin/env python3
"""Apply script: backfill NULL default columns even when the column already existed.

Run from the HealthCross repo root: python3 apply_migrate_backfill_existing_columns.py
IMPORTANT: after applying, RESTART the server so the corrected backfill actually
runs against your real database.
"""
import base64, hashlib, os, sys

MARKER = "MIGRATE_BACKFILL_EXISTING_COLUMNS_2026_08_05"

FILES = [
    {
        'path': 'app/db_migrate.py',
        'sha256': 'b444b966d8a6d6310ddbe9e8d6f5f08cf532b62a5d30c9a58c69ccb9eff37658',
        'size': 3500,
        'b64': '',
    },
    {
        'path': 'tests/test_db_migrate.py',
        'sha256': '25a9949c14c171f43bfa534e46c720d8a9d5382fbd511797fac29893b095b373',
        'size': 5657,
        'b64': '',
    },
]


def main():
    repo_root = os.getcwd()
    ok = True
    for entry in FILES:
        path = os.path.join(repo_root, entry['path'])
        data = base64.b64decode(entry['b64'])
        if len(data) != entry['size']:
            print(f"SIZE MISMATCH before write: {entry['path']}")
            ok = False
            continue
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as f:
            f.write(data)
        with open(path, 'rb') as f:
            written = f.read()
        actual_sha = hashlib.sha256(written).hexdigest()
        if actual_sha == entry['sha256']:
            print(f"OK  {entry['path']}  ({len(written)} bytes, sha256={actual_sha[:12]}...)")
        else:
            print(f"CHECKSUM MISMATCH  {entry['path']}  expected={entry['sha256'][:12]}... actual={actual_sha[:12]}...")
            ok = False
    if ok:
        print(f"\nAll files written and verified. Marker: {MARKER}")
        print("Next: python3 -m pytest -q   (should show 496 passed)")
        print("Then RESTART the server (./start_healthcross.sh) so the corrected backfill runs.")
        print("Then: git add -A && git commit -m '...' && git push")
    else:
        print("\nSOME FILES FAILED TO VERIFY - do not commit. Re-run this script once more first.")
        sys.exit(1)


if __name__ == '__main__':
    main()
